import { Component, EventEmitter, Output } from '@angular/core';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-login-dialog',
  templateUrl: './login-dialog.component.html',
  styleUrls: ['./login-dialog.component.css']
})
export class LoginDialogComponent {
  @Output() close = new EventEmitter<void>();
  @Output() loginSuccess = new EventEmitter<void>();
  @Output() switchToRegister = new EventEmitter<void>();

  email = '';
  password = '';
  submitting = false;
  error: string | null = null;

  constructor(private authService: AuthService) {}

  onSubmit() {
    if (!this.email || !this.password) {
      this.error = 'Bitte fülle alle Felder aus.';
      return;
    }

    this.submitting = true;
    this.error = null;

    this.authService.login(this.email, this.password).subscribe({
      next: (response) => {
        if (response.success) {
          this.loginSuccess.emit();
        } else {
          this.error = response.message;
        }
        this.submitting = false;
      },
      error: (error) => {
        console.error('Login-Fehler:', error);
        this.error = error.error?.message || 'Login fehlgeschlagen. Bitte versuche es erneut.';
        this.submitting = false;
      }
    });
  }

  onClose() {
    this.close.emit();
  }

  onSwitchToRegister() {
    this.switchToRegister.emit();
  }

  onBackdropClick(event: MouseEvent) {
    if (event.target === event.currentTarget) {
      this.onClose();
    }
  }
}
<div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" (click)="onBackdropClick($event)">
  <div class="bg-white rounded-lg shadow-xl w-full max-w-md mx-4 p-8">
    <!-- Header -->
    <div class="flex justify-between items-center mb-6">
      <h2 class="text-2xl text-gray-900">Anmelden</h2>
      <button 
        (click)="onClose()"
        class="text-gray-400 hover:text-gray-600">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
        </svg>
      </button>
    </div>

    <!-- Error Message -->
    <div *ngIf="error" class="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
      <p class="text-sm text-red-800">{{ error }}</p>
    </div>

    <!-- Form -->
    <form (ngSubmit)="onSubmit()">
      <div class="mb-4">
        <label class="block text-sm text-gray-700 mb-2">E-Mail</label>
        <input
          type="email"
          [(ngModel)]="email"
          name="email"
          required
          placeholder="deine@email.com"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent">
      </div>

      <div class="mb-6">
        <label class="block text-sm text-gray-700 mb-2">Passwort</label>
        <input
          type="password"
          [(ngModel)]="password"
          name="password"
          required
          placeholder="••••••••"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent">
      </div>

      <button
        type="submit"
        [disabled]="submitting"
        class="w-full px-6 py-3 bg-orange-600 text-white rounded-lg hover:bg-orange-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors mb-4">
        {{ submitting ? 'Wird angemeldet...' : 'Anmelden' }}
      </button>

      <p class="text-center text-sm text-gray-600">
        Noch kein Konto?
        <button
          type="button"
          (click)="onSwitchToRegister()"
          class="text-orange-600 hover:text-orange-700 ml-1">
          Jetzt registrieren
        </button>
      </p>
    </form>
  </div>
</div>
